%[text] # Creating Delta V Surrogate
%%
AU = 1.49579151285e8;
mu_star = 1.32712440018e11; % [km3 / s2]
l_star = AU; % [km] one AU
m_star = 3000; % [kg] - max initial ship mass
a_star = mu_star / l_star ^ 2; % [km / s2]
t_star = sqrt(l_star ^ 3 / mu_star);
v_star = sqrt(mu_star/l_star);

year_to_sec = 86400.0 * 365.25;

u_max = 0.6; % [N]
mu = 1;
mu_dim = mu_star;
m0 = 3000 / m_star * 0.35;
m_min = 500 / m_star; % dependent on a lot
t0 = 13.5 * year_to_sec / t_star;
ToF = 0.5 * year_to_sec / t_star;
tf = ToF;
tf_actual = t0 + ToF;
N = 15;

%% Calculate max dV possible for continuous max thrust (ignoring external forces)
Isp = 4000; % [s]
g_0 = 9.80665; % [m / s2]
alpha = 1 / (Isp * g_0); % [s / m]

mf = m0 - alpha * u_max * tf * t_star / m_star;
dV_max = Isp * g_0 * log(m0 / mf) / 1000 / v_star;
%%
% Load data sets
load("dataset_1to4000IDs_0p5ToF_13p5yr_0p35m.mat")
dataset_0p8ToF_13p2yr = dataset;
dV_filter = dataset_0p8ToF_13p2yr.dV_lambert / dV_max > 0;
dataset_0p8ToF_13p2yr.dV_lambert = dataset_0p8ToF_13p2yr.dV_lambert(dV_filter);
dataset_0p8ToF_13p2yr.dV_lowthrust = dataset_0p8ToF_13p2yr.dV_lowthrust(dV_filter);
dataset_0p8ToF_13p2yr.dV_ratio = dataset_0p8ToF_13p2yr.dV_ratio(dV_filter);
dataset_0p8ToF_13p2yr.v1_ast = dataset_0p8ToF_13p2yr.v1_ast(:, dV_filter);
dataset_0p8ToF_13p2yr.v2_ast = dataset_0p8ToF_13p2yr.v2_ast(:, dV_filter);
dataset_0p8ToF_13p2yr.v1_lambert = dataset_0p8ToF_13p2yr.v1_lambert(:, dV_filter);
dataset_0p8ToF_13p2yr.v2_lambert = dataset_0p8ToF_13p2yr.v2_lambert(:, dV_filter);
dataset_0p8ToF_13p2yr.x_1 = dataset_0p8ToF_13p2yr.x_1(:, dV_filter);
dataset_0p8ToF_13p2yr.x_2 = dataset_0p8ToF_13p2yr.x_2(:, dV_filter);
%%
x_1_me = keplerian_to_modified_equinoctial_array(dataset_0p8ToF_13p2yr.x_1', [])';
x_2_me = keplerian_to_modified_equinoctial_array(dataset_0p8ToF_13p2yr.x_2', [])';
%%
figure %[output:7dad5b1b]
%scatter3(dataset_0p8ToF_13p2yr.dV_lambert, dataset_0p8ToF_13p2yr.dV_lowthrust, x_1_me(5, :) - x_2_me(5, :)); hold on
scatter3(dataset_0p8ToF_13p2yr.dV_lambert / dV_max, dataset_0p8ToF_13p2yr.dV_lowthrust / dV_max, angdiff(x_1_me(6, :), x_2_me(6, :))); hold on %[output:7dad5b1b]
xlabel("Lambert dV [km / s]") %[output:7dad5b1b]
ylabel("Low Thrust dV [km / s]") %[output:7dad5b1b]
title("Low Thrust dV vs Lambert dV") %[output:7dad5b1b]
subtitle(sprintf("For %.1f Month Asteroid Transfers at Year %.2f", dataset_0p8ToF_13p2yr.ToF * t_star / year_to_sec * 12, t0 * t_star / year_to_sec)) %[output:7dad5b1b]
grid on %[output:7dad5b1b]
hold off %[output:7dad5b1b]
%%
figure %[output:48ddbf7e]
scatter(dataset_0p8ToF_13p2yr.dV_lambert / dV_max, dataset_0p8ToF_13p2yr.dV_ratio) %[output:48ddbf7e]
%%
fitResult_x = {};
%%
h = histfit(dataset_0p8ToF_13p2yr.dV_lambert / dV_max, 100, "normal"); %[output:65df9d66]
fitResult_dV_lambert = fitdist(dataset_0p8ToF_13p2yr.dV_lambert' / dV_max, "Normal") % Fit the model to the data %[output:6d24c5c1]
%%
histfit(angdiff(x_1_me(6, :), x_2_me(6, :)), 100, "lognormal") %[output:5dd49efa]
fitResult_x_me6diff = fitdist(angdiff(x_1_me(6, :), x_2_me(6, :))', "Lognormal") % Fit the model to the data %[output:021bf31b]
%%
histfit(dataset_0p8ToF_13p2yr.v1_ast(3, :) - dataset_0p8ToF_13p2yr.v1_lambert(3, :), 100, "normal") %[output:11aaaf2e]
fitResult_vdiff{1}{1} = fitdist(dataset_0p8ToF_13p2yr.v1_ast(1, :)' - dataset_0p8ToF_13p2yr.v1_lambert(1, :)', "Normal");
fitResult_vdiff{1}{2} = fitdist(dataset_0p8ToF_13p2yr.v2_ast(1, :)' - dataset_0p8ToF_13p2yr.v2_lambert(1, :)', "Normal");
fitResult_vdiff{2}{1} = fitdist(dataset_0p8ToF_13p2yr.v1_ast(2, :)' - dataset_0p8ToF_13p2yr.v1_lambert(2, :)', "Normal");
fitResult_vdiff{2}{2} = fitdist(dataset_0p8ToF_13p2yr.v2_ast(2, :)' - dataset_0p8ToF_13p2yr.v2_lambert(2, :)', "Normal");
fitResult_vdiff{3}{1} = fitdist(dataset_0p8ToF_13p2yr.v1_ast(3, :)' - dataset_0p8ToF_13p2yr.v1_lambert(3, :)', "Normal");
fitResult_vdiff{3}{2} = fitdist(dataset_0p8ToF_13p2yr.v2_ast(3, :)' - dataset_0p8ToF_13p2yr.v2_lambert(3, :)', "Normal");

histfit(dataset_0p8ToF_13p2yr.v2_ast(3, :) - dataset_0p8ToF_13p2yr.v2_lambert(3, :), 100, "normal") %[output:8b1ee128]
%%
%[text] ## Surrogate Model using Modified Equinoctial
%[text] 12 Inputs: Lambert dV, x\_1\_me(1:5), x\_2\_me(1:5), angle difference of true longitude         - (give both dV for lambert or actual vecter info? asteroid velocity vectors?)
%[text] 1 Output: Low thrust dV / Lambert dV        - (or just low thrust dV?)
uqlab %[output:21ce6b59]
%%
X_inputs = [dataset_0p8ToF_13p2yr.v1_ast(1, :) - dataset_0p8ToF_13p2yr.v1_lambert(1, :);
            dataset_0p8ToF_13p2yr.v2_ast(1, :) - dataset_0p8ToF_13p2yr.v2_lambert(1, :);
            dataset_0p8ToF_13p2yr.v1_ast(2, :) - dataset_0p8ToF_13p2yr.v1_lambert(2, :);
            dataset_0p8ToF_13p2yr.v2_ast(2, :) - dataset_0p8ToF_13p2yr.v2_lambert(2, :);
            dataset_0p8ToF_13p2yr.v1_ast(3, :) - dataset_0p8ToF_13p2yr.v1_lambert(3, :);
            dataset_0p8ToF_13p2yr.v2_ast(3, :) - dataset_0p8ToF_13p2yr.v2_lambert(3, :);
            dataset_0p8ToF_13p2yr.dV_lambert / dV_max];


index = 1;

InputOpts = [];

% Asteroid and lambert velocity vector differences
for i = 1 : 3
    for j = 1 : 2
        InputOpts.Marginals(index).Name = sprintf('vdiff_%g_%g', j, i);
        InputOpts.Marginals(index).Type = fitResult_vdiff{i}{j}.DistributionName; 
        InputOpts.Marginals(index).Moments = fitResult_vdiff{i}{j}.ParameterValues; % matlab always match UQ lab?
        index = index + 1;
    end
end

% Lambert delta V
InputOpts.Marginals(index).Name = 'dVLambert';
InputOpts.Marginals(index).Type = fitResult_dV_lambert.DistributionName;
InputOpts.Marginals(index).Moments = fitResult_dV_lambert.ParameterValues;
%InputOpts.Marginals(index).Bounds = [0, 1];
index = index + 1;

for i = 1 : numel(InputOpts.Marginals)
    if strcmp(InputOpts.Marginals(i).Type, 'Normal')
        InputOpts.Marginals(i).Type = 'Gaussian';
    end
end

myInput = uq_createInput(InputOpts);

uq_print(myInput); %[output:28fa3425]
%%
% Fit
MetaOpts = [];
MetaOpts.Type = 'Metamodel';
MetaOpts.MetaType = 'PCE';

train_portion = 0.7;
indices = [ones([1, floor(train_portion * numel(dataset_0p8ToF_13p2yr.dV_lambert))]), zeros([1, ceil((1 - train_portion) * numel(dataset_0p8ToF_13p2yr.dV_lambert))])];
train_i = logical(indices(randperm(numel(indices))));
test_i = ~train_i;

MetaOpts.ExpDesign.X = X_inputs(:, train_i)';
MetaOpts.ExpDesign.Y = dataset_0p8ToF_13p2yr.dV_lowthrust(train_i)' / dV_max;

MetaOpts.Degree = 1:3;
MetaOpts.Method = 'LARS';

MetaOpts.ValidationSet.X = X_inputs(:, test_i)';
MetaOpts.ValidationSet.Y = dataset_0p8ToF_13p2yr.dV_lowthrust(test_i)' / dV_max;

%MetaOpts.PolyTypes = {'legendre','legendre','legendre','legendre','legendre','legendre','legendre','legendre','legendre','legendre','legendre','legendre'};
%MetaOpts.PolyTypes = {'arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary'};

myPCE = uq_createModel(MetaOpts); %[output:47686c82]
uq_print(myPCE) %[output:1319c2d0]
uq_display(myPCE) %[output:81e3a680]
%%
%[text] ## Validation
Yval = dataset_0p8ToF_13p2yr.dV_lowthrust(test_i)' / dV_max;

Ylamb = dataset_0p8ToF_13p2yr.dV_lambert(test_i)' / dV_max;

YPCE = uq_evalModel(myPCE, X_inputs(:, test_i)');

uq_figure %[output:2a26ec79]

cmap = uq_colorOrder(3);
uq_histogram(Ylamb, 'FaceColor', cmap(1,:)) %[output:2a26ec79]
hold on %[output:2a26ec79]
uq_histogram(Yval, 'FaceColor', cmap(2,:)) %[output:2a26ec79]
hold on %[output:2a26ec79]
uq_histogram(YPCE, 'FaceColor', cmap(3,:)) %[output:2a26ec79]
hold off %[output:2a26ec79]

xlabel('$\mathrm{Y}$') %[output:2a26ec79]
ylabel('Counts') %[output:2a26ec79]
uq_legend(... %[output:group:19f8ce07] %[output:2a26ec79]
    {'Lambert', 'True model response', 'PCE prediction'},... %[output:2a26ec79]
    'Location', 'northwest') %[output:group:19f8ce07] %[output:2a26ec79]

uq_figure
%%
uq_plot(Ylamb, Yval, 'x') %[output:1e03c127]
hold on %[output:1e03c127]
uq_plot(YPCE, Yval, '+') %[output:1e03c127]
hold on %[output:1e03c127]
uq_plot([min(Yval) max(Yval)], [min(Yval) max(Yval)], 'k') %[output:1e03c127]
hold off %[output:1e03c127]

axis equal %[output:1e03c127]
axis([min(Yval) max(Yval) min(Yval) max(Yval)]) %[output:1e03c127]

ylabel('$\mathrm{Y_{true}}$') %[output:1e03c127]
xlabel('$\mathrm{Y_{Lamb,PCE}}$') %[output:1e03c127]
legend("Lamb", "PCE") %[output:1e03c127]
%%
fprintf('PCE metamodel validation error: %5.4e\n', myPCE.Error.Val) %[output:72673191]
fprintf('PCE metamodel LOO error:        %5.4e\n', myPCE.Error.LOO) %[output:6a215a4a]
%%
%% Sobol Indices Sensitivity Analysis
% Set up analysis
SobolOpts.Type = 'Sensitivity';
SobolOpts.Method = 'Sobol';
SobolOpts.Sobol.Order = 1;

% Run analysis
mySobolAnalysisPCE = uq_createAnalysis(SobolOpts); %[output:07a98d15]

%% Display Sensitivity Analysis Results
uq_display(mySobolAnalysisPCE) %[output:0c5ddbe1] %[output:128a9151]
%%\
uq_figure() %[output:45a79634]
uq_bar(1:numel(mySobolAnalysisPCE.Results.Total), mySobolAnalysisPCE.Results.Total, 0.25) %[output:45a79634]
% Set axes limits
ylim([0 1]) %[output:45a79634]
% Set labels
xlabel('Variable name') %[output:45a79634]
ylabel('Total Sobol'' indices') %[output:45a79634]
set(gca, 'XTick', 1:length(InputOpts.Marginals),... %[output:45a79634]
    'XTickLabel', mySobolAnalysisPCE.Results.VariableNames) %[output:45a79634]
% Set Title
title(sprintf('PCE-based Sobol Indice Sensitivity Analysis (%d simulations)', myPCE.ExpDesign.NSamples)) %[output:45a79634]
% Set legend
uq_legend({... %[output:group:9b18a398] %[output:7241a78a] %[output:45a79634]
    "Final $\sigma_{r_x}$", "Final $\sigma_{r_y}$"},... %[output:7241a78a] %[output:45a79634]
    'Location', 'northeast', "Interpreter", "latex") %[output:group:9b18a398] %[output:7241a78a] %[output:45a79634]
%%
%[text] ## dV ratio
% Fit
MetaOpts.Type = 'Metamodel';
MetaOpts.MetaType = 'PCE';

train_portion = 0.7;
indices = [ones([1, floor(train_portion * numel(dataset_0p8ToF_13p2yr.dV_lambert))]), zeros([1, ceil((1 - train_portion) * numel(dataset_0p8ToF_13p2yr.dV_lambert))])];
train_i = logical(indices(randperm(numel(indices))));
test_i = ~train_i;

MetaOpts.ExpDesign.X = X_inputs(:, train_i)';
%MetaOpts.ExpDesign.Y = dataset_0p8ToF_13p2yr.dV_lowthrust(train_i)' / dV_max;
MetaOpts.ExpDesign.Y = dataset_0p8ToF_13p2yr.dV_ratio(train_i)';

MetaOpts.Degree = 1:3;

MetaOpts.ValidationSet.X = X_inputs(:, test_i)';
%MetaOpts.ValidationSet.Y = dataset_0p8ToF_13p2yr.dV_lowthrust(test_i)' / dV_max;
MetaOpts.ValidationSet.Y = dataset_0p8ToF_13p2yr.dV_ratio(test_i)';

myPCE_ratio = uq_createModel(MetaOpts); %[output:90a7077a]
uq_print(myPCE_ratio) %[output:861a51f6]
uq_display(myPCE_ratio) %[output:93f0ec97]
%%
%[text] ## Validation
Yval = dataset_0p8ToF_13p2yr.dV_lowthrust(test_i)' / dV_max;
%Yval = dataset_0p8ToF_13p2yr.dV_ratio(test_i)';

Ylamb = dataset_0p8ToF_13p2yr.dV_lambert(test_i)' / dV_max;
%Ylamb = ones(size(Yval));

YPCE = uq_evalModel(myPCE_ratio, X_inputs(:, test_i)') .* dataset_0p8ToF_13p2yr.dV_lambert(test_i)' / dV_max;

uq_figure %[output:0ffd9292]

cmap = uq_colorOrder(3);
uq_histogram(Ylamb, 'FaceColor', cmap(1,:)) %[output:0ffd9292]
hold on %[output:0ffd9292]
uq_histogram(Yval, 'FaceColor', cmap(2,:)) %[output:0ffd9292]
hold on %[output:0ffd9292]
uq_histogram(YPCE, 'FaceColor', cmap(3,:)) %[output:0ffd9292]
hold off %[output:0ffd9292]

xlabel('$\mathrm{Y}$') %[output:0ffd9292]
ylabel('Counts') %[output:0ffd9292]
uq_legend(... %[output:group:8e6cf10c] %[output:0ffd9292]
    {'Lambert', 'True model response', 'PCE prediction'},... %[output:0ffd9292]
    'Location', 'northwest') %[output:group:8e6cf10c] %[output:0ffd9292]

uq_figure
%%
uq_plot(Ylamb, Yval, 'x') %[output:7ec77cc5]
hold on %[output:7ec77cc5]
uq_plot(YPCE, Yval, '+') %[output:7ec77cc5]
hold on %[output:7ec77cc5]
uq_plot([min(Yval) max(Yval)], [min(Yval) max(Yval)], 'k') %[output:7ec77cc5]
hold off %[output:7ec77cc5]

axis equal %[output:7ec77cc5]
axis([min(Yval) max(Yval) min(Yval) max(Yval)]) %[output:7ec77cc5]

ylabel('$\mathrm{Y_{true}}$') %[output:7ec77cc5]
xlabel('$\mathrm{Y_{Lamb,PCE}}$') %[output:7ec77cc5]
legend("Lamb", "PCE") %[output:7ec77cc5]
%%
fprintf('PCE metamodel validation error: %5.4e\n', myPCE_ratio.Error.Val) %[output:1bedce02]
fprintf('PCE metamodel LOO error:        %5.4e\n', myPCE_ratio.Error.LOO) %[output:328fe73b]
%%
%% Sobol Indices Sensitivity Analysis
% Set up analysis
SobolOpts.Type = 'Sensitivity';
SobolOpts.Method = 'Sobol';
SobolOpts.Sobol.Order = 1;

% Run analysis
mySobolAnalysisPCE = uq_createAnalysis(SobolOpts); %[output:1e8de300]

%% Display Sensitivity Analysis Results
uq_display(mySobolAnalysisPCE) %[output:985f7f45] %[output:746b1b10]
